/*
 * Watchtower service worker.
 *
 * Deliberately hand-written rather than generated by a plugin. A bundler would
 * precache the entire build output, which on a metered 2G connection is the
 * wrong trade for a safety app: what actually needs to work offline is the app
 * shell and the icons, so that a cold launch renders something honest instead of
 * a browser error page.
 *
 * Four rules this file will not break:
 *
 *   1. Never cache or intercept /api. An SOS must always hit the network. A
 *      cached "alert sent" response replayed from a cache is how a safety app
 *      ends up lying to somebody's family.
 *   2. Never cache live location. A stale map of where a frightened person is
 *      standing is not a degraded feature, it is a misleading one.
 *   3. Navigations are network-first with an offline fallback. Only the public
 *      pages named in PUBLIC_NAVIGATIONS are stored; an authenticated page is
 *      never written to a cache, because a cache is keyed by URL rather than by
 *      session and would hand the previous user's dashboard to the next person
 *      to open the app on this device.
 *   4. A failed navigation answers with the offline page rather than whatever
 *      happened to be cached, so "no connection" never looks like "signed in".
 */

const VERSION = "watchtower-v2";
const SHELL_CACHE = `${VERSION}-shell`;
const STATIC_CACHE = `${VERSION}-static`;

/** The minimum needed to render something rather than nothing. */
const SHELL_URLS = ["/offline", "/icon.svg", "/icon-192.png"];

/**
 * The only navigations allowed into a persistent cache.
 *
 * A Cache Storage entry is keyed by URL, not by session, so caching an
 * authenticated page means the next person to open the app on this device can
 * read the previous person's dashboard, Guardian Circle, and journey history
 * straight out of the cache while signed out or locked. An allowlist is the
 * only safe shape here: everything else goes to the network and, on failure,
 * the honest offline page.
 */
const PUBLIC_NAVIGATIONS = new Set(["/offline", "/sign-in", "/sign-up"]);

const isPublicNavigation = (pathname) => PUBLIC_NAVIGATIONS.has(pathname);

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // Individually, so one missing file does not fail the whole install and
      // leave the phone with no service worker at all.
      .then((cache) => Promise.allSettled(SHELL_URLS.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((key) => key !== SHELL_CACHE && key !== STATIC_CACHE).map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

const isApiOrStream = (url) =>
  url.pathname.startsWith("/api/") || url.pathname.startsWith("/track/");

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Rule 1. Only GET is cacheable, and never anything under /api.
  if (request.method !== "GET") {
    return;
  }

  const url = new URL(request.url);

  // Same-origin only. A cross-origin request is Mapbox's tile server, which
  // manages its own caching and should not be double-cached here.
  if (url.origin !== self.location.origin) {
    return;
  }

  if (isApiOrStream(url)) {
    return;
  }

  if (request.mode === "navigate") {
    const cacheable = isPublicNavigation(url.pathname);

    event.respondWith(
      fetch(request)
        .then((response) => {
          if (response.ok && cacheable) {
            const copy = response.clone();
            void caches.open(SHELL_CACHE).then((cache) => cache.put(request, copy));
          }
          return response;
        })
        .catch(async () => {
          // An authenticated page is never served from cache, so the only honest
          // offline answer for one is the offline page itself.
          if (!cacheable) {
            const offline = await caches.match("/offline");
            if (offline !== undefined) {
              return offline;
            }
            return Response.error();
          }

          const cached = await caches.match(request);
          return cached ?? (await caches.match("/offline")) ?? Response.error();
        }),
    );
    return;
  }

  // Build output and images are content-hashed, so cache-first is safe and is
  // what makes a repeat launch free.
  if (url.pathname.startsWith("/_next/static/") || url.pathname.endsWith(".png") || url.pathname.endsWith(".svg")) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            if (response.ok) {
              const copy = response.clone();
              void caches.open(STATIC_CACHE).then((cache) => cache.put(request, copy));
            }
            return response;
          }),
      ),
    );
  }
});
